
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_revtpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_revtpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.783131822675990e+00, -4.686223345267323e+00, -4.550354220641320e+00, -4.361983408133631e+00, -4.104983644206875e+00, -3.762314768554643e+00, -3.320207284076951e+00, -2.776436825447233e+00, -2.155073567829849e+00, -1.528332967147948e+00, -9.963852796992121e-01, -6.886412495202658e-01, -5.995991951318311e-01, -5.076675922614625e-01, -3.615178239501987e-01, -2.228705384051244e-01, -1.252046012738720e-01, -4.901720192767779e-02, -1.080650830572228e-02, -1.216194253504090e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


